  `therapist_id` int(11) NOT NULL,
  `month` int(11) NOT NULL,
  `year` int(11) NOT NULL,
  `sessions_count` int(11) DEFAULT NULL,
  `avg_score` float DEFAULT NULL,
  `objectives_achieved` int(11) DEFAULT NULL,
  `objectives_total` int(11) DEFAULT NULL,
  `report_text` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_monthly_report` (`patient_id`,`therapist_id`,`month`,`year`),
  KEY `therapist_id` (`therapist_id`),
  CONSTRAINT `monthly_report_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `user` (`id`),
  CONSTRAINT `monthly_report_ibfk_2` FOREIGN KEY (`therapist_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
